   301|async function requestIVXAIAnswer(input: {
   302|  message: string;
   303|  history: PublicChatHistoryItem[];
   304|  sessionId: string;
   305|  businessContext: string | null;
   306|  images: PublicChatImageAttachment[];
   307|  documents: DealDocumentAttachment[];
   308|  extractedDocuments: ExtractedDocument[];
   309|  videoUnderstandings: VideoUnderstanding[];
   310|}): Promise<PublicChatAnswerResult> {
   311|  const endpoint = getGatewayModelEndpoint();
   312|  if (!isPublicChatAIConfigured() || !endpoint) {
   313|    throw new Error('IVX AI proxy configuration is missing.');
   314|  }
   315|
   316|  const promptParts = [
   317|    'Recent public chat transcript:',
   318|    buildTranscript(input.history),
   319|    '',
   320|  ];
   321|  if (input.businessContext) {
   322|    promptParts.push(input.businessContext, '');
   323|  }
   324|  if (input.images.length > 0) {
   325|    promptParts.push(
   326|      `Note: ${input.images.length} image attachment(s) accompany this message — analyze them as part of your answer.`,
   327|      '',
   328|    );
   329|  }
   330|  if (input.documents.length > 0) {
   331|    promptParts.push(
   332|      `Note: ${input.documents.length} deal-room document(s) accompany this message: ${input.documents
   333|        .map((doc) => `${doc.name ?? doc.url} [${doc.kind}] ${doc.url}`)
   334|        .join('; ')}. Analyze them as an acquisition analyst per the instructions above.`,
   335|      '',
   336|    );
   337|  }
   338|  const extractedContentBlock = buildExtractedDocumentContentBlock(input.extractedDocuments);
   339|  if (extractedContentBlock) {
   340|    promptParts.push(extractedContentBlock, '');
   341|  }
   342|  const videoContentBlock = buildVideoUnderstandingBlock(input.videoUnderstandings);
   343|  if (videoContentBlock) {
   344|    promptParts.push(videoContentBlock, '');
   345|  }
   346|  promptParts.push(
   347|    `User message: ${input.message || (input.images.length > 0 ? 'Analyze the attached image(s).' : '')}`,
   348|    '',
   349|    'Reply directly to the user message. If the user asks for an exact token or proof string, include it exactly.',
   350|  );
   351|
   352|  const result = await requestIVXAIText({
   353|    module: 'public-chat',
   354|    requestId: input.sessionId,
   355|    model: getPublicChatModel(),
   356|    system: buildSystemPrompt(
   357|      input.sessionId,
   358|      input.images.length > 0,
   359|      input.documents,
   360|      extractedContentBlock,
   361|      videoContentBlock,
   362|      input.message,
   363|    ),
   364|    prompt: promptParts.join('\n'),
   365|    images: input.images.length > 0 ? input.images : undefined,
   366|  });
   367|
   368|  return {
   369|    answer: result.text,
   370|    model: result.providerMetadata.model,
   371|    source: 'chatgpt',
   372|    endpoint: result.providerMetadata.endpoint,
   373|    imageCount: input.images.length,
   374|    providerMetadata: result.providerMetadata,
   375|  };
   376|}
