   378|export async function generatePublicChatAnswer(input: {
   379|  message: string;
   380|  history: PublicChatHistoryItem[];
   381|  sessionId: string;
   382|  images?: PublicChatImageAttachment[];
   383|  documents?: DealDocumentAttachment[];
   384|  /** Raw attachment payload used to detect video attachments for video reading. */
   385|  rawAttachments?: unknown;
   386|  /** Whether a verified owner session is present. Defaults to false (unauthenticated public chat). */
   387|  ownerSessionPresent?: boolean;
   388|  /** Real developer proof attached to this turn, if any. */
   389|  developerProof?: { taskId: string; filesChanged: string[]; commitSha: string | null; renderDeployId: string | null; liveHttpStatus: number | null } | null;
   390|}): Promise<PublicChatAnswerResult> {
   391|  const ownerSessionPresent = input.ownerSessionPresent ?? false;
   392|  const developerProof = input.developerProof ?? null;
   393|  const history = sanitizePublicChatHistory(input.history);
   394|  const images = (input.images ?? [])
   395|    .map((img) => ({ url: typeof img.url === 'string' ? img.url.trim() : '', mimeType: img.mimeType ?? null }))
   396|    .filter((img) => img.url.length > 0);
   397|  const documents = (input.documents ?? []).filter((doc) => typeof doc.url === 'string' && doc.url.trim().length > 0);
   398|  const videos = extractVideoAttachments(input.rawAttachments ?? { videos: [], attachments: [] });
   399|
   400|  // ── IVX IA Identity Brain ───────────────────────────────────────────────
   401|  // Direct, deterministic answers for identity / ownership / IVXHOLDINGS project
   402|  // questions ("what is your name", "who created you", "who is your owner",
   403|  // "what is IVX", project & investment questions). Fast path — never blocks.
   404|  const identityAnswer = resolveIVXIdentityAnswer(input.message);
   405|  if (identityAnswer) {
   406|    console.log('[PublicChatAI] Identity brain answered:', {
   407|      sessionId: input.sessionId,
   408|      marker: IVX_IA_IDENTITY_MARKER,
   409|    });
   410|    return {
   411|      answer: identityAnswer,
   412|      model: 'ivx-ia-identity-brain',
   413|      source: 'fallback',
   414|      endpoint: null,
   415|      imageCount: images.length,
   416|    };
   417|  }
   418|
   419|  // ── IVX IA Conversation Brain ───────────────────────────────────────────
   420|  // General conversation questions (math, greetings, help, capabilities, thanks)
   421|  // answered directly — never blocks, never asks for proof.
   422|  const conversationAnswer = resolveIVXConversationAnswer(input.message);
   423|  if (conversationAnswer) {
   424|    console.log('[PublicChatAI] Conversation brain answered:', {
   425|      sessionId: input.sessionId,
   426|      marker: IVX_IA_CONVERSATION_MARKER,
   427|    });
   428|    return {
   429|      answer: conversationAnswer,
   430|      model: 'ivx-ia-conversation-brain',
   431|      source: 'fallback',
   432|      endpoint: null,
   433|      imageCount: images.length,
   434|    };
   435|  }
   436|
   437|  // ── Authoritative Intent Router (Item 5) ──────────────────────────────
   438|  // The SINGLE source of truth for public chat routing. Safe technical and
   439|  // educational questions are allowed without owner auth. Code changes,
   440|  // deployments, private data, owner controls, and destructive actions are
   441|  // blocked. This replaces the old 5-branch router which was blocking safe
   442|  // code-review and architecture questions with OWNER_SESSION_MISSING.
   443|  const authoritativeDecision = classifyIntent({
   444|    message: input.message,
   445|    isOwner: ownerSessionPresent,
   446|    isPublicPath: true,
   447|    hasImageAttachments: images.length > 0,
   448|  });
   449|  console.log('[PublicChatAI] Authoritative intent router:', {
   450|    sessionId: input.sessionId,
   451|    traceId: authoritativeDecision.traceId,
   452|    intent: authoritativeDecision.intent,
   453|    confidence: authoritativeDecision.confidence,
   454|    route: authoritativeDecision.selectedRoute,
   455|    reason: authoritativeDecision.reason,
   456|    publicBoundary: authoritativeDecision.safetyStage.publicBoundary,
   457|  });
   458|
   459|  // Public chat: block execution, deployment, destructive actions, owner controls
   460|  // Vague execution requests ("fix the production problem", "deploy this") on
   461|  // public chat get a helpful LLM response instead of a canned auth block.
   462|  // The LLM will ask what the problem is and explain that execution requires
   463|  // owner login — far more useful than a generic auth wall.
   464|  // This applies to BOTH CLARIFICATION and DEVELOPER_WORKER routes — the
   465|  // authoritative router classifies vague execution as DEVELOPER_WORKER, but
   466|  // on public chat we still want a helpful LLM diagnostic, not a block.
   467|  const isVagueExec = isVagueExecutionRequest(input.message);
   468|  const isExecutionRoute = authoritativeDecision.selectedRoute === 'CLARIFICATION'
   469|    || authoritativeDecision.selectedRoute === 'DEVELOPER_WORKER'
   470|    || authoritativeDecision.selectedRoute === 'DEPLOYMENT_ACTION';
   471|  // On public chat (no owner session), vague execution requests get a helpful
   472|  // LLM diagnostic instead of a canned auth block. This applies regardless of
   473|  // publicBoundary — the authoritative router may classify "fix the production
   474|  // problem" as DEVELOPER_WORKER with public_safe boundary (no explicit blocked
   475|  // pattern matches), but we still want the LLM to ask what the problem is
   476|  // rather than returning a useless auth wall.
   477|  if (isExecutionRoute && !ownerSessionPresent && isVagueExec) {
   478|    console.log('[PublicChatAI] Vague execution request on public chat — routing to LLM for helpful diagnostic:', {
   479|      sessionId: input.sessionId,
   480|      intent: authoritativeDecision.intent,
   481|      route: authoritativeDecision.selectedRoute,
   482|      publicBoundary: authoritativeDecision.safetyStage.publicBoundary,
   483|    });
   484|    // Fall through to the LLM call below
   485|  } else if (isExecutionRoute && authoritativeDecision.safetyStage.publicBoundary === 'public_blocked') {
   486|    return {
   487|      answer: `This request requires owner authentication. Safe technical questions, code reviews, architecture designs, and product information are available without login. Try rephrasing your question if you want an explanation rather than an execution.`,
   488|      model: 'ivx-authoritative-router',
   489|      source: 'fallback' as PublicChatSource,
   490|      endpoint: null,
   491|      imageCount: images.length,
   492|    };
   493|  }
   494|
   495|  // Public chat: safe knowledge questions go straight to LLM (no owner auth needed)
   496|  if (authoritativeDecision.selectedRoute === 'PUBLIC_LLM_RESPONSE') {
   497|    // Fall through to the LLM call below — the authoritative router
   498|    // has confirmed this is a safe question (explanation, architecture,
   499|    // code review, conversation, business analysis)
   500|    console.log('[PublicChatAI] Safe public question allowed:', {
   501|      sessionId: input.sessionId,
   502|      intent: authoritativeDecision.intent,
   503|      confidence: authoritativeDecision.confidence,
   504|    });
